css:
:root { --font-sans: "Ubuntu Sans", "Ubuntu", system-ui, sans-serif; --font-mono: "Ubuntu Sans Mono", "Ubuntu Mono", ui-monospace, monospace; --wa-rule: #44576C; --wa-rule-width: 1.5px; }
.dark { --wa-rule: #9FB2C6; }
.chat-markdown { font-size: 0.9375rem; }
.chat-markdown :is(p, ul, ol, blockquote, h1, h2, h3, h4) { max-width: 72ch; }
[data-user-message-bubble] { font-size: 0.9375rem; line-height: 1.6; }

/* Sidebar edge */
[data-slot="sidebar-container"] { border-color: var(--sidebar-border) !important; }

/* Divider below Needs you: the Threads heading's own top border, in slate */
[data-slot="sidebar-inner"] [data-slot="sidebar-group"] > h2 { border-top: var(--wa-rule-width) solid var(--wa-rule) !important; }

/* Working: its own solid tray with the slate rule on top */
[data-slot="sidebar-inner"] section:has([data-sidebar-row="shelf:working"]) { position: relative; z-index: 1; margin-top: 0.5rem !important; padding-bottom: 0.375rem; background-color: #FBFAF7; border-top: var(--wa-rule-width) solid var(--wa-rule) !important; box-shadow: 0 -6px 12px -10px rgba(40,44,50,.18); --sidebar-stage-fade: #FBFAF7; }
.dark [data-slot="sidebar-inner"] section:has([data-sidebar-row="shelf:working"]) { background-color: #282B30; box-shadow: none; --sidebar-stage-fade: #282B30; }

/* Pale print at the foot of the sidebar */
:root:not(.dark) [data-slot="sidebar-inner"] { background-image: linear-gradient(180deg, #F1EFEA 0%, #F1EFEA 56%, rgba(241,239,234,.55) 80%, rgba(241,239,234,0) 100%), var(--theme-background-image) !important; background-size: cover, cover !important; background-position: center, 55% 60% !important; background-repeat: no-repeat !important; }

/* New, empty thread: the photo fills the area; a soft paper glow keeps the headline and composer clear */
:root:not(.dark) [data-workspace-area="conversation"]:has(~ [data-chat-composer-overlay] h1) [data-timeline-loading] { background-image: radial-gradient(ellipse 40rem 15rem at 50% calc(50% - 1.75rem), #FFFFFF 0%, #FFFFFF 50%, rgba(255,255,255,.6) 72%, rgba(255,255,255,0) 100%), var(--theme-background-image) !important; background-size: auto, cover !important; background-position: center, 50% 60% !important; background-repeat: no-repeat !important; filter: brightness(.9) contrast(1.25); }

/* No-project headline */
[data-chat-composer-overlay] h1:not(:has(*)):has(+ p [data-draft-project-trigger]) { font-size: 0 !important; line-height: 0 !important; }
[data-chat-composer-overlay] h1:not(:has(*)):has(+ p [data-draft-project-trigger])::after { content: "What are we climbing today?"; display: block; font-size: 1.5rem; line-height: 2rem; }
@media (min-width: 40rem) { [data-chat-composer-overlay] h1:not(:has(*)):has(+ p [data-draft-project-trigger])::after { font-size: 1.875rem; line-height: 2.25rem; } }
